import { ScriptedAgent } from './agent.js';

const TEST_FILE = 'hello.test.js';

/** Generates one node:test case per acceptance criterion. */
export function generateTests(criteria) {
  const cases = criteria.map((c) => {
    const args = c.call.args.map((a) => JSON.stringify(a)).join(', ');
    return [
      `test(${JSON.stringify(`${c.id}: ${c.description}`)}, () => {`,
      `  assert.equal(greet(${args}), ${JSON.stringify(c.expected)});`,
      '});',
    ].join('\n');
  });
  return [
    '// Generated by the scripted QA agent from the PO acceptance criteria.',
    "import test from 'node:test';",
    "import assert from 'node:assert/strict';",
    "import { greet } from './hello.js';",
    '',
    cases.join('\n\n'),
    '',
  ].join('\n');
}

export class QaAgent extends ScriptedAgent {
  constructor() {
    super({
      id: 'qa',
      name: 'QA',
      role: 'Quality Assurance',
      summary: 'Turns acceptance criteria into tests, runs them and reports the results.',
      responsibilities: ['Writes tests from acceptance criteria', 'Runs the test suite', 'Reports pass/fail'],
    });
  }

  async perform(_task, { acceptance }) {
    if (!acceptance?.length) throw new Error('QA needs acceptance criteria before it can test');
    return {
      messages: [
        `Generated ${acceptance.length} tests in ${TEST_FILE}, one per acceptance criterion.`,
        'Running them with the Node.js built-in test runner.',
      ],
      actions: [
        { type: 'writeFile', path: TEST_FILE, purpose: 'Tests derived from acceptance criteria', content: generateTests(acceptance) },
        { type: 'runTests', files: [TEST_FILE] },
      ],
    };
  }

  async review(_task, _context, actionResults) {
    const run = actionResults.find((r) => r.type === 'runTests');
    const { summary, tests, exitCode, timedOut } = run;
    const failed = tests.filter((t) => t.status === 'fail');
    const passed = exitCode === 0 && !timedOut && failed.length === 0 && summary.tests > 0;

    const messages = [
      `Test runner exited with code ${exitCode}${timedOut ? ' (timed out)' : ''}: ` +
        `${summary.tests ?? 0} tests, ${summary.pass ?? 0} passed, ${summary.fail ?? 0} failed.`,
    ];
    for (const test of failed) messages.push(`FAILED ${test.name}: expected "${test.expected}", got "${test.actual}".`);
    messages.push(passed ? 'Verdict: all acceptance tests pass.' : 'Verdict: acceptance tests are failing.');

    return { messages, output: { verdict: passed ? 'pass' : 'fail' } };
  }
}
